def _g(x):
    return -0.003684 + _g_0(x) + _g_1(x) + _g_2(x) + _g_3(x) + _g_4(x) + _g_5(x) + _g_6(x) + _g_7(x) + _g_8(x) + _g_9(x) + _g_10(x) + _g_11(x) + _g_12(x) + _g_13(x) + _g_14(x) + _g_15(x) + _g_16(x) + _g_17(x) + _g_18(x) + _g_19(x) + _g_20(x) + _g_21(x) + _g_22(x) + _g_23(x) + _g_24(x) + _g_25(x) + _g_26(x) + _g_27(x) + _g_28(x) + _g_29(x) + _g_30(x) + _g_31(x) + _g_32(x) + _g_33(x) + _g_34(x) + _g_35(x) + _g_36(x) + _g_37(x) + _g_38(x) + _g_39(x)

def site_covariates(wx, soil_raw, lon):
    """Six covariates from the full-record weather dict {year: {doy: row}} and the soil layer list (thick, clay, sand, soc per layer)."""
    gs_t, gs_s, gs_r, n = 0.0, 0.0, 0.0, 0
    for y in wx:
        for d, r in wx[y].items():
            if 121 <= d <= 273:
                gs_t += (r["tx"] + r["tn"]) / 2.0
                gs_s += r["solar"]
                gs_r += (r["rhx"] + r["rhn"]) / 2.0
                n += 1
    tot = sum(l["thick"] for l in soil_raw)
    top = soil_raw[:3]
    return {
        "soc_prof": sum((l["soc"] or 0.2) * l["thick"] for l in soil_raw) / tot,
        "clay_top": sum(l["clay"] for l in top) / len(top),
        "gs_tmean": gs_t / n, "gs_solar": gs_s / n, "gs_rh": gs_r / n, "lon": lon,
    }


def regional_params(wx, soil_raw, lon):
    """Returns (net_n_multiplier, grain_factor) for a site."""
    x = site_covariates(wx, soil_raw, lon)
    m = min(M_RANGE[1], max(M_RANGE[0], math.exp(_m(x))))
    g = min(G_RANGE[1], max(G_RANGE[0], math.exp(_g(x))))
    return m, g
